      if($('businessGrid'))$('businessGrid').innerHTML='<div class="empty">'+esc(translatedCopy('برای نمایش بیزینس‌های مجاز، ابتدا پروژه را دریافت می‌کنیم…'))+'</div>';
      if($('businessSummary'))$('businessSummary').innerHTML='<div class="empty">'+esc(translatedCopy('پروفایل پروژه در دسترس نیست.'))+'</div>';
      if($('userRows'))$('userRows').innerHTML='<tr><td colspan="4" class="empty">'+esc(translatedCopy('در حال دریافت کاربران مجاز…'))+'</td></tr>';
      if($('sessionRows'))$('sessionRows').innerHTML='<tr><td colspan="4" class="empty">'+esc(translatedCopy('در حال دریافت نشست‌های مجاز…'))+'</td></tr>';
