    async function checkAssistantReadiness(id){try{const r=await req('/admin/api/assistants/'+id+'/readiness');const labels={business_profile:'پروفایل بیزینس',sources:'رسانه‌ها',topics:'موضوعات',feedback_channel:'کانال فیدبک',observer_channel:'کانال مشاهده',runtime_settings:'تنظیمات اجرایی',activation:'فعال‌سازی'};const checks=Object.entries(r.checks||{}).map(([key,ok])=>`<div class="detail-item"><span>${esc(labels[key]||key)}</span><b class="${ok?'up':'down'}">${ok?'آماده':'ناقص'}</b></div>`).join('');const missing=(r.missing||[]).map(x=>labels[x]||x).join('، ');modal('بررسی آمادگی دستیار',`<div class="notice ${r.ready?'':'warn'}">${r.ready?'این دستیار برای اجرا آماده است.':'این دستیار هنوز آماده اجرا نیست. موارد لازم در زیر مشخص شده‌اند.'}</div><div class="detail-list">${checks||'<div class="empty">نتیجه‌ای دریافت نشد.</div>'}</div>${missing?`<p class="muted" data-ui-css="declaration-1">موارد لازم: ${esc(missing)}</p>`:''}`,()=>closeModal(),'بستن')}catch(err){toast('بررسی آمادگی انجام نشد: '+friendlyError(err.message),true)}}
