    function relevanceBadge(x){if(['published','edited','publishing'].includes(x.status))return status(x.status);const i={selected:0,borderline:1,rejected:2,pending:3}[x.relevance_state]??3;return '<span class="status '+(i===0?'active':i===2?'failed':'review')+'">'+esc(relevanceCopy()[i])+'</span>'}
