    function renderPublications(){const q=($('publicationSearch')?.value||'').trim().toLowerCase(),st=$('publicationStatus')?.value||'';const rows=state.publications.filter(x=>(!st||(st==='review_only'?x.review_only&&x.relevance_state!=='rejected':st==='rejected'?(x.status==='rejected'||x.relevance_state==='rejected'):x.status===st))&&(!q||((cleanPublicationText(x.message_text||''))+' '+(x.status||'')+' '+(x.relevance_state||'')+' '+(x.source_name||'')).toLowerCase().includes(q)));const pageSize=20,page=Math.max(1,Math.min(state.publicationPage||1,Math.max(1,Math.ceil(rows.length/pageSize)))),start=(page-1)*pageSize,visible=rows.slice(start,start+pageSize);state.publicationPage=page;$('publicationCount').textContent=state.language==='en'?`${rows.length} items`:`${toFaDigits(rows.length)} مورد`;$('publicationRows').innerHTML=visible.map(x=>{const publicationStatus=relevanceBadge(x);const score=x.relevance_score==null?'—':Number(x.relevance_score).toFixed(2);return `<tr><td class="publication-news-cell" data-ui-css="declaration-2"><button class="btn small" data-ui-click="openPublication('${esc(x.id)}')">${esc(cleanPublicationText(x.message_text||'بدون متن').slice(0,120))}</button></td><td><div>${publicationStatus}</div></td><td class="muted" data-latin="true">${esc(score)}</td><td class="muted">${esc(x.source_name||x.source_key||'—')}</td><td class="muted">${fmtDate(x.article_published_at||x.created_at)}</td><td class="muted">${fmtDate(x.published_at)}</td></tr>`}).join('')||`<tr><td colspan="6" class="empty">${state.language==='en'?'No news matches these filters.':'موردی با این فیلتر پیدا نشد.'}</td></tr>`;const pager=$('publicationPager');if(pager){const totalPages=Math.max(1,Math.ceil(rows.length/pageSize));pager.innerHTML=totalPages>1?`<button class="btn small" type="button" data-publication-page="prev" ${page===1?'disabled':''}>${state.language==='en'?'Previous':'قبلی'}</button>${Array.from({length:totalPages},(_,i)=>`<button class="btn small ${i+1===page?'primary':''}" type="button" data-publication-page="${i+1}">${toFaDigits(i+1)}</button>`).join('')}<button class="btn small" type="button" data-publication-page="next" ${page===totalPages?'disabled':''}>${state.language==='en'?'Next':'بعدی'}</button>`:'';pager.querySelectorAll('[data-publication-page]').forEach(button=>button.addEventListener('click',()=>{const value=button.dataset.publicationPage;state.publicationPage=value==='prev'?Math.max(1,page-1):value==='next'?Math.min(totalPages,page+1):Number(value);renderPublications()}))}}
    async function publishFromReview(id){const x=state.publications.find(item=>item.id===id);if(!x)return;const en=state.language==='en';const endpoint=x.review_only?'/publications/'+id+'/approve-borderline':'/publications/'+id+'/publish';modal(en?'Confirm publication':'تأیید انتشار',`<div class="notice warn">${en?'The complete news has been reviewed. Publish it to the Telegram channel now?':'خبر کامل را مرور کردین. آیا اکنون آن را در کانال تلگرام منتشر می‌کنین؟'}</div><div class="article-body" data-ui-css="declaration-3">${esc(cleanPublicationText(x.message_text||''))}</div>`,async()=>{try{$('modalSubmit').disabled=true;await req(endpoint,{method:'POST'});closeModal();$('closeDrawer').click();toast(en?'News approved and published':'خبر تأیید و منتشر شد');state.publicationPage=1;await loadAll()}catch(err){$('modalSubmit').disabled=false;toast(friendlyError(err.message),true)}},en?'Approve & publish':'تأیید و انتشار')}
    async function approveBorderline(id){return publishFromReview(id)}
    function renderSources(){const q=($('sourceSearch')?.value||'').toLowerCase();const rows=state.sources.filter(x=>(x.name||x.source_key||'').toLowerCase().includes(q));$('sourceCount').textContent=`${rows.length} رسانه`;$('sourceRows').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.name||x.source_key)}</b><div class="muted">${esc(x.source_key||'')}</div></td><td>${esc(x.adapter||'—')}</td><td><span class="source-health"><i class="health-dot ${esc(x.health_status)}"></i>${esc(x.health_status||'unknown')}</span></td><td>${esc(x.priority??'—')}</td><td class="muted">${fmtDate(x.last_success_at)}</td><td><button class="btn small" data-ui-click="toggleSource('${esc(x.id)}',${!x.enabled})">${x.enabled?'غیرفعال':'فعال'}</button><button class="btn small" data-ui-click="openSourceModal('${esc(x.id)}')">تنظیمات</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">رسانه‌ای پیدا نشد.</td></tr>'}
    function renderTopics(){const q=($('topicSearch')?.value||'').toLowerCase();const rows=state.topics.filter(x=>(x.name||x.topic_key||'').toLowerCase().includes(q));$('topicCount').textContent=`${rows.length} موضوع`;$('topicRows').innerHTML=rows.map(x=>`<tr><td><b>${esc(x.name)}</b><div class="muted">${esc(x.topic_key)}</div></td><td>${'★'.repeat(Number(x.importance||0))}</td><td>${Number(x.threshold||0).toFixed(2)}</td><td>${x.enabled?'<span class="status active">فعال</span>':'<span class="status paused">خاموش</span>'}</td><td><button class="btn small" data-ui-click="toggleTopic('${esc(x.id)}',${!x.enabled})">${x.enabled?'خاموش‌کردن':'فعال‌کردن'}</button><button class="btn small" data-ui-click="openTopicModal('${esc(x.id)}')">تنظیمات</button></td></tr>`).join('')||'<tr><td colspan="5" class="empty">موضوعی پیدا نشد.</td></tr>'}
    function renderTelegram(){if(!state.assistantId){$('telegramStatus').className='status';$('telegramStatus').textContent='پروژه‌ای انتخاب نشده';$('telegramDetails').innerHTML='<div class="empty">برای نمایش تنظیمات، یک پروژهٔ مجاز را انتخاب کنین.</div>';return}const p=state.telegram?.permission||{};$('telegramStatus').className='status '+(p.ready?'active':'failed');$('telegramStatus').textContent=p.ready?'آماده':'نیازمند بررسی';$('telegramDetails').innerHTML=[['ربات',p.bot_username||'—'],['عضویت',p.member_status||'—'],['ارسال',p.can_post?'مجاز':'بررسی شود'],['ویرایش',p.can_edit?'مجاز':'بررسی شود'],['خطا',p.error||'بدون خطا']].map(x=>`<div class="detail-item"><span>${esc(x[0])}</span><b>${esc(x[1])}</b></div>`).join('')}
    function renderOperations(){const m=state.meta||{},p=m.pipeline||{},q=m.queues||{},owner=Boolean(state.currentUser?.is_owner||state.currentUser?.role==='owner'),label=(fa,en)=>window.__miLabel?window.__miLabel(fa,en):(state.language==='en'?en:fa),shown=value=>value===null||value===undefined||value==='—'?'—':(state.language==='en'?String(value):toFaDigits(value));$('operationHealth').className='status active';$('operationHealth').textContent=label('سرویس فعال','Service active');$('operationMeta').innerHTML=[[label('نسخه','Version'),m.version],[label('محیط','Environment'),m.environment],[label('منطقهٔ زمانی','Timezone'),m.timezone],[label('زمان‌بندی انتشار','Publication scheduler'),state.scheduler?.enabled?label('فعال','Enabled'):label('خاموش','Disabled')]].map(x=>`<div class="detail-item"><span>${esc(x[0])}</span><b>${esc(x[1]??'—')}</b></div>`).join('');const collectionRows=owner?[ [label('خزش و تحلیل','Collection & analysis'),state.scheduler?.collection_enabled===false?label('غیرفعال','Disabled'):label('فعال','Enabled')], [label('ساعات خزش هفتگی','Weekly collection hours'),shown(state.scheduler?.collection_schedule_slots?.length||0)], [label('سقف تحلیل هر اجرا','Per-run analysis cap'),shown(state.runtimeSettings?.collection_max_items_per_run)], [label('بودجهٔ روزانهٔ تحلیل','Daily analysis budget'),shown(state.runtimeSettings?.collection_max_items_per_day)] ]:[];$('analysisMeta').innerHTML=[[label('مدل','Model'),p.model],[label('بردارسازی','Embedding'),m.embedding_model||'—'],[label('آستانهٔ ارتباط','Relevance threshold'),p.relevance_threshold],[label('انتشار خودکار','Automatic publication'),p.auto_publish?label('فعال','Enabled'):label('خاموش','Disabled')],...collectionRows].map(x=>`<div class="detail-item"><span>${esc(x[0])}</span><b>${esc(x[1]??'—')}</b></div>`).join('');$('queueMeta').innerHTML=[[label('اجراها','Runs'),q.runs],[label('صف خطا','Dead letter'),q.dead_letter],[label('قفل زمان‌بندی','Scheduler lock'),q.scheduler_lock],[label('ظرفیت روزانه مدل','Daily model capacity'),shown(p.daily_model_request_cap||'—')]].map(x=>`<div class="detail-item"><span>${esc(x[0])}</span><b>${esc(x[1]??'—')}</b></div>`).join('')}
    async function loadBusiness(){try{state.business=await req('/admin/api/business-profile');if($('businessSummary'))$('businessSummary').innerHTML=[['نام بیزینس',state.business.business_name],['محصولات/خدمات',state.business.products_services],['مشتریان هدف',state.business.target_customers],['بازارها',state.business.markets],['زبان خروجی',state.business.output_language]].map(x=>`<div class="detail-item"><span>${esc(x[0])}</span><b data-ui-css="declaration-4">${esc(x[1]||'—')}</b></div>`).join('')}catch(err){if($('businessSummary'))$('businessSummary').innerHTML='<div class="empty">پروفایل بیزینس در دسترس نیست.</div>'}}
    async function loadUsers(){try{const [u,s]=await Promise.all([req('/admin/api/users'),req('/admin/api/sessions')]);$('userRows').innerHTML=(u.users||[]).map(x=>`<tr><td><b>${esc(x.username)}</b></td><td>${esc(x.role)}</td><td>${x.active?'<span class="status active">فعال</span>':'<span class="status paused">غیرفعال</span>'}</td><td><button class="btn small" data-ui-click="editUser('${esc(x.id)}','${esc(x.username)}','${esc(x.role)}',${x.active})">ویرایش</button></td></tr>`).join('')||'<tr><td colspan="4" class="empty">کاربری وجود ندارد.</td></tr>';$('sessionRows').innerHTML=(s.sessions||[]).map(x=>`<tr><td>${esc(x.username)}</td><td class="muted">${fmtDate(x.created_at)}</td><td class="muted">${fmtDate(x.expires_at)}</td><td>${x.current?'<span class="status active">جاری</span>':`<button class="btn small danger" data-ui-click="revokeSession('${esc(x.id)}')">لغو</button>`}</td></tr>`).join('')||'<tr><td colspan="4" class="empty">نشست فعالی وجود ندارد.</td></tr>'}catch(err){toast(friendlyError(err.message),true)}}
    async function loadQuality(){try{const r=await req('/feedback/report?days=30');const total=r.total_feedback??r.count??0,rel=r.relevant??r.related??0,irr=r.irrelevant??r.unrelated??0;$('qualityTotal').textContent=total;$('qualityRelevant').textContent=rel;$('qualityIrrelevant').textContent=irr;$('qualityReport').textContent=JSON.stringify(r,null,2)}catch(err){$('qualityReport').textContent=friendlyError(err.message)}}
    let modalOpener=null;
    function label(fa,english){return localeLabel(fa,english)}
    function modal(title,body,submit,submitLabel='ذخیره'){modalOpener=document.activeElement;$('modalRoot').innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="adminModalTitle" tabindex="-1"><div class="modal-head"><h3 id="adminModalTitle">${title}</h3><button class="modal-close" aria-label="${label('بستن پنجره','Close dialog')}" data-ui-click="closeModal()">×</button></div>${body}<div class="modal-foot"><button class="btn primary" id="modalSubmit">${esc(submitLabel)}</button><button class="btn" data-ui-click="closeModal()">${label('انصراف','Cancel')}</button></div></div></div>`;$('modalRoot').classList.remove('hidden');$('modalSubmit').onclick=submit;translateStaticCopy();requestAnimationFrame(()=>{const root=$('modalRoot'),dialog=root.querySelector('[role="dialog"]');if(dialog&&!dialog.dataset.keyboardBound){dialog.dataset.keyboardBound='1';dialog.addEventListener('keydown',event=>{if(event.key==='Escape'){event.preventDefault();closeModal();return}if(event.key!=='Tab')return;const items=[...dialog.querySelectorAll('button:not([disabled]),a[href],input:not([disabled]),select:not([disabled]),textarea:not([disabled]),[tabindex]:not([tabindex="-1"])')].filter(node=>!node.hidden&&node.getAttribute('aria-hidden')!=='true'&&node.getClientRects().length);if(!items.length){event.preventDefault();dialog.focus();return}const first=items[0],last=items[items.length-1];if(event.shiftKey&&(document.activeElement===first||!dialog.contains(document.activeElement))){event.preventDefault();last.focus()}else if(!event.shiftKey&&(document.activeElement===last||!dialog.contains(document.activeElement))){event.preventDefault();first.focus()}});const initial=dialog.querySelector('input:not([disabled]),select:not([disabled]),textarea:not([disabled]),button:not([disabled])');(initial||dialog).focus()}try{window.__researchBeeEnhanceInfoTips?.()}catch(_){}})}
    function closeModal(){const opener=modalOpener;modalOpener=null;$('modalRoot').classList.add('hidden');$('modalRoot').innerHTML='';requestAnimationFrame(()=>{if(opener?.isConnected)opener.focus()})}
    function openAssistantModal(id=''){const x=state.assistants.find(a=>a.id===id)||{};modal(id?'ویرایش دستیار':'ساخت دستیار',`<div class="form-grid"><div class="field"><label>نام دستیار</label><input id="fName" value="${esc(x.name||'')}" placeholder="مثلاً Bee Researcher داتین"></div><div class="field"><label>نام بیزینس</label><input id="fBusiness" value="${esc(x.business_name||'')}" placeholder="نام بیزینس"></div>${id?'':'<div class="field"><label>شناسه یکتا (slug)</label><input id="fSlug" value="" placeholder="dotin-research"></div>'}<div class="field full"><label>توضیح</label><textarea id="fDescription" placeholder="هدف این دستیار و محدوده کاری آن">${esc(x.description||'')}</textarea></div>${id?`<div class="field"><label>وضعیت</label><select id="fStatus"><option ${x.status==='draft'?'selected':''} value="draft">پیش‌نویس</option><option ${x.status==='testing'?'selected':''} value="testing">در حال تست</option><option ${x.status==='active'?'selected':''} value="active">فعال</option><option ${x.status==='paused'?'selected':''} value="paused">متوقف</option></select></div>`:''}</div>`,async()=>{try{const body={name:$('fName').value,business_name:$('fBusiness').value,description:$('fDescription').value};let created=null;if(id){body.status=$('fStatus').value;body.config=x.config||{};await req('/admin/api/assistants/'+id,{method:'PATCH',body:JSON.stringify(body)})}else{body.slug=$('fSlug').value;created=await req('/admin/api/assistants',{method:'POST',body:JSON.stringify(body)})}closeModal();toast('دستیار ذخیره شد');await loadAll();if(created?.id){state.assistantId=created.id;localStorage.setItem('research_bee_workspace',created.id);await loadAll();checkAssistantReadiness(created.id)}}catch(err){toast(friendlyError(err.message),true)}})}
    function openCloneAssistantModal(id){const source=state.assistants.find(a=>a.id===id);if(!source)return;const en=state.language==='en';const suffix='-copy';const suggestedSlug=((source.slug||'assistant').replace(/[^a-z0-9-]/g,'').slice(0,55)||'assistant')+suffix;modal(en?'Copy assistant as draft':'کپی دستیار به‌عنوان پیش‌نویس',`<div class="notice">${en?'The configuration, media and topics are copied without Telegram credentials or destinations. The new assistant is always created as a draft.':'تنظیمات، رسانه‌ها و موضوعات کپی می‌شوند؛ اما اعتبارنامه و مقصد تلگرام منتقل نمی‌شود. دستیار جدید همیشه به‌صورت پیش‌نویس ساخته می‌شود.'}</div><div class="form-grid"><div class="field"><label>${en?'Assistant name':'نام دستیار'}</label><input id="cloneName" value="${esc((source.name||'')+' (کپی)')}" maxlength="160"></div><div class="field"><label>${en?'Business name':'نام بیزینس'}</label><input id="cloneBusiness" value="${esc(source.business_name||'')}" maxlength="160"></div><div class="field"><label>${en?'Unique slug':'شناسه یکتا (slug)'}</label><input id="cloneSlug" value="${esc(suggestedSlug)}" maxlength="64" pattern="[a-z0-9][a-z0-9-]{2,63}"></div><div class="field full"><label>${en?'Description':'توضیح'}</label><textarea id="cloneDescription" maxlength="4000">${esc(source.description||'')}</textarea></div></div>`,async()=>{try{const created=await req('/admin/api/assistants/'+encodeURIComponent(id)+'/clone',{method:'POST',body:JSON.stringify({slug:$('cloneSlug').value.trim(),name:$('cloneName').value.trim(),business_name:$('cloneBusiness').value.trim(),description:$('cloneDescription').value})});closeModal();toast(en?'Draft assistant created':'دستیار پیش‌نویس ساخته شد');await loadAll();if(created?.id){state.assistantId=created.id;localStorage.setItem('research_bee_workspace',created.id);await loadAll();checkAssistantReadiness(created.id)}}catch(err){toast(friendlyError(err.message),true)}},en?'Create draft':'ساخت پیش‌نویس')}
    async function openQuickAssistantModal(){
      const en=state.language==='en';
      modal(en?'Quick assistant setup':'ساخت سریع دستیار',`<div class="notice">${en?'Describe the monitoring mission in a few words. A suggested setup will be generated first; nothing is saved until you review and confirm it.':'هدف پایش را کوتاه توضیح دهید. ابتدا تنظیمات پیشنهادی ساخته می‌شود؛ تا زمانی که شما بررسی و تأیید نکنید چیزی ذخیره نمی‌شود.'}</div><div class="field full"><label>${en?'Short mission':'توضیح کوتاه مأموریت'}</label><textarea id="quickMission" minlength="8" maxlength="2000" placeholder="مثلاً اخبار فین‌تک اروپا و اثر آن بر پرداخت دیجیتال را هر روز پایش کن."></textarea></div>`,async()=>{const mission=$('quickMission').value.trim();if(mission.length<8){toast(en?'Please describe the mission in at least 8 characters.':'مأموریت را حداقل در ۸ نویسه توضیح دهید.',true);return}try{const r=await req('/admin/api/assistants/draft',{method:'POST',body:JSON.stringify({mission,language:state.language==='en'?'en':'fa'})});closeModal();openAssistantDraftReview(r.draft||{})}catch(err){toast(friendlyError(err.message),true)}},en?'Generate suggestion':'ساخت پیشنهاد');
    }
    function openAssistantDraftReview(draft){const en=state.language==='en',settings=draft.settings||{},sources=(draft.source_suggestions||[]).join('\n'),topics=(draft.topic_suggestions||[]).join('\n');modal(en?'Review quick setup':'مرور تنظیمات پیشنهادی',`<div class="notice">${en?'Edit any field before creating the assistant. Suggested media and topics are notes only and are not connected automatically.':'همه فیلدها قابل ویرایش‌اند. رسانه‌ها و موضوعات پیشنهادی فقط یادداشت‌اند و بدون تأیید شما متصل نمی‌شوند.'}</div><div class="form-grid"><div class="field"><label>${en?'Assistant name':'نام دستیار'}</label><input id="draftName" value="${esc(draft.name||'')}"></div><div class="field"><label>${en?'Business name':'نام بیزینس'}</label><input id="draftBusiness" value="${esc(draft.business_name||'')}"></div><div class="field"><label>Slug</label><input id="draftSlug" value="${esc(draft.slug||'')}"></div><div class="field"><label>${en?'Freshness window (days)':'پنجره تازگی (روز)'}</label><input id="draftFreshness" type="number" min="1" max="7" value="${esc(settings.freshness_window_days||3)}"></div><div class="field full"><label>${en?'Description':'توضیح'}</label><textarea id="draftDescription">${esc(draft.description||draft.mission||'')}</textarea></div><div class="field"><label>${en?'Suggested media':'رسانه‌های پیشنهادی'}</label><textarea id="draftSources" readonly>${esc(sources)}</textarea></div><div class="field"><label>${en?'Suggested topics':'موضوعات پیشنهادی'}</label><textarea id="draftTopics" readonly>${esc(topics)}</textarea></div></div>`,async()=>{try{const body={slug:$('draftSlug').value.trim(),name:$('draftName').value.trim(),business_name:$('draftBusiness').value.trim(),description:$('draftDescription').value,config:{...draft.config,runtime:{...(draft.config?.runtime||{}),freshness_window_days:Number($('draftFreshness').value||3)}}};const created=await req('/admin/api/assistants',{method:'POST',body:JSON.stringify(body)});closeModal();toast(en?'Assistant created as a draft':'دستیار به‌صورت پیش‌نویس ساخته شد');await loadAll();if(created?.id){state.assistantId=created.id;localStorage.setItem('research_bee_workspace',created.id);await loadAll();checkAssistantReadiness(created.id)}}catch(err){toast(friendlyError(err.message),true)}},en?'Create draft':'ساخت پیش‌نویس')}
    async function activateAssistant(id){if(!confirm('این دستیار فعال شود؟'))return;try{await req('/admin/api/assistants/'+id+'/activate',{method:'POST'});toast('دستیار فعال شد');loadAll()}catch(err){toast(friendlyError(err.message),true)}}
