      const isSource=kind==='source', label=isSource?'رسانه':'موضوع', endpoint=isSource?'sources':'topics';
      const inputId=isSource?'draftSourceName':'draftTopicName', instructionId='draftInstruction';
      modal('بررسی و افزودن '+label,`<div class="notice">فقط نام را وارد کنین؛ شناسه پس از ثبت نهایی خودکار ساخته می‌شود. بررسی حداکثر یک دقیقه زمان می‌برد.</div><div class="form-grid"><div class="field full"><label>${isSource?'نام رسانه':'عنوان موضوع'}</label><input id="${inputId}" autocomplete="off"></div><div class="field full"><label>توضیح یا زاویهٔ موردنظر (اختیاری)</label><textarea id="${instructionId}" placeholder="مثلاً تمرکز بر اثر آن بر بازار ایران"></textarea></div></div>`,async()=>{const name=$(inputId).value.trim();if(!name){toast('نام را وارد کنین',true);$(inputId)?.focus();return}const button=$('modalSubmit');button.disabled=true;button.textContent='در حال بررسی…';try{const r=await req('/admin/api/assistants/'+encodeURIComponent(state.assistantId)+'/'+endpoint+'/draft',{method:'POST',body:JSON.stringify({name,instruction:$(instructionId).value.trim()})});renderCatalogDraft(kind,r.draft||{},name)}catch(err){/* Keep the catalog usable if the optional AI request is unavailable. The local draft is explicit and editable; final persistence still goes through the same scoped API and validation. */const fallback=isSource?{name,homepage_url:'',fetch_url:'',adapter:'rss',language:state.language==='en'?'en':'fa',region:state.language==='en'?'global':'IR',priority:3,access_notes:'',research_notes:'بررسی خودکار در دسترس نبود؛ آدرس عمومی رسانه را وارد کنین.'}:{name,definition:'پوشش و تحلیل اخبار مرتبط با «'+name+'».',positive_terms:[name],negative_terms:[],importance:3,threshold:0.45,research_notes:'بررسی خودکار در دسترس نبود؛ تعریف موضوع و واژه‌ها را مرور کنین.'};renderCatalogDraft(kind,fallback,name)}} ,'بررسی')
