    function renderCatalogDraft(kind,draft,originalName){
      const isSource=kind==='source', label=isSource?'رسانه':'موضوع', split=v=>(Array.isArray(v)?v:(v||'').split(',')).map(x=>String(x).trim()).filter(Boolean);
      const fields=isSource?`<div class="field"><label>نام رسانه</label><input id="dfName" value="${esc(draft.name||originalName)}"></div><div class="field"><label>نوع اتصال</label><select id="dfAdapter"><option value="rss" ${draft.adapter==='rss'?'selected':''}>RSS</option><option value="html" ${draft.adapter==='html'?'selected':''}>HTML</option><option value="json" ${draft.adapter==='json'?'selected':''}>JSON</option></select></div><div class="field"><label>صفحه اصلی</label><input id="dfHome" type="url" value="${esc(draft.homepage_url||'')}"></div><div class="field"><label>RSS / ورودی دریافت</label><input id="dfFeed" type="url" value="${esc(draft.fetch_url||'')}"></div><div class="field"><label>اولویت</label><input id="dfPriority" type="number" min="1" max="5" value="${esc(draft.priority??3)}"></div><div class="field full"><label>یادداشت دسترسی</label><textarea id="dfNotes">${esc(draft.access_notes||'')}</textarea></div>`:`<div class="field full"><label>عنوان موضوع</label><input id="dfName" value="${esc(draft.name||originalName)}"></div><div class="field"><label>اهمیت (۱ تا ۵)</label><input id="dfImportance" type="number" min="1" max="5" value="${esc(draft.importance??3)}"></div><div class="field"><label>آستانه ارتباط</label><input id="dfThreshold" type="number" min="0" max="1" step=".01" value="${esc(draft.threshold??.45)}"></div><div class="field full"><label>تعریف موضوع</label><textarea id="dfDefinition">${esc(draft.definition||'')}</textarea></div><div class="field full"><label>واژه‌های مثبت (با کاما)</label><input id="dfPositive" value="${esc(split(draft.positive_terms).join(', '))}"></div><div class="field full"><label>واژه‌های منفی (با کاما)</label><input id="dfNegative" value="${esc(split(draft.negative_terms).join(', '))}"></div>`;
      modal('پیش‌نویس '+label,`<div class="notice">${esc(draft.research_notes||'پیش‌نویس آماده است؛ قبل از ثبت آن را مرور کنید.')}</div><div class="form-grid">${fields}<div class="field full"><label>توضیح برای بررسی دوباره (اختیاری)</label><textarea id="retryInstruction" placeholder="چه زاویه‌ای اصلاح یا بررسی شود؟"></textarea></div></div><div class="muted" data-ui-css="declaration-6">می‌توانید ویرایش کنید، دوباره بررسی بزنین یا لغو کنید.</div><button type="button" class="btn small" id="retryDraftBtn">بررسی دوباره</button>`,async()=>{try{const body=isSource?{name:$('dfName').value.trim(),homepage_url:$('dfHome').value.trim(),fetch_url:$('dfFeed').value.trim(),adapter:$('dfAdapter').value,priority:Number($('dfPriority').value),access_notes:$('dfNotes').value.trim()}:{name:$('dfName').value.trim(),importance:Number($('dfImportance').value),threshold:Number($('dfThreshold').value),definition:$('dfDefinition').value.trim(),positive_terms:split($('dfPositive').value),negative_terms:split($('dfNegative').value)};const created=await req('/admin/api/assistants/'+state.assistantId+'/'+(isSource?'sources':'topics'),{method:'POST',body:JSON.stringify(body)});closeModal();toast(label+' ثبت شد');await loadAll();if(isSource&&created?.id)window.probeSingleSource?.(created.id)}catch(err){toast(friendlyError(err.message),true)}},'ثبت نهایی');
      $('retryDraftBtn').onclick=async()=>{try{$('retryDraftBtn').disabled=true;$('retryDraftBtn').textContent='در حال بررسی…';const r=await req('/admin/api/assistants/'+state.assistantId+'/'+(isSource?'sources':'topics')+'/draft',{method:'POST',body:JSON.stringify({name:$('dfName').value.trim(),instruction:$('retryInstruction').value.trim()})});renderCatalogDraft(kind,r.draft||{},$('dfName').value.trim())}catch(err){$('retryDraftBtn').disabled=false;$('retryDraftBtn').textContent='بررسی دوباره';toast(friendlyError(err.message),true)}};
    }
    async function loadSourceSuggestions(){
      if(!state.assistantId||!$('sourceSuggestionsRows'))return;
      try{
        const payload=await req('/admin/api/assistants/'+state.assistantId+'/source-suggestions');
        const rows=payload.suggestions||[],en=state.language==='en',owner=payload.can_approve===true;
        $('sourceSuggestionsCard').classList.toggle('hidden',!rows.length);
        $('sourceSuggestionsRows').innerHTML=rows.map(x=>{const d=x.draft||{};const status=x.status==='pending'?(en?'Pending owner approval':'در انتظار تأیید مالک'):x.status==='approved'?(en?'Approved':'تأییدشده'):(en?'Rejected':'ردشده');return `<div class="channel-card" data-ui-css="declaration-7"><div class="channel-card-head"><div><b>${esc(d.name||x.name||'—')}</b><span class="muted">${esc(d.research_notes||'')}</span></div><span class="status ${x.status==='approved'?'active':x.status==='rejected'?'failed':'draft'}">${status}</span></div><div class="detail-list"><div class="detail-item"><span>${en?'Why it fits':'دلیل تناسب'}</span><b>${esc(d.fit_reason||'—')}</b></div><div class="detail-item"><span>${en?'Example article':'نمونه خبر'}</span><b>${esc(d.example_article||'—')}</b></div><div class="detail-item"><span>${en?'Overlap with current sources':'هم‌پوشانی با منابع فعلی'}</span><b>${esc(d.overlap_notes||'—')}</b></div><div class="detail-item"><span>${en?'Homepage':'صفحه اصلی'}</span><b data-latin="true">${esc(d.homepage_url||'—')}</b></div><div class="detail-item"><span>${en?'Feed':'فید'}</span><b data-latin="true">${esc(d.fetch_url||'—')}</b></div></div>${owner&&x.status==='pending'?`<div class="card-actions" data-ui-css="declaration-7"><button class="btn small primary" data-source-suggestion-approve="${esc(x.id)}">${en?'Approve and add':'تأیید و افزودن'}</button><button class="btn small danger" data-source-suggestion-reject="${esc(x.id)}">${en?'Reject':'رد'}</button></div>`:''}</div>`}).join('');
        document.querySelectorAll('[data-source-suggestion-approve]').forEach(b=>b.onclick=async()=>{try{const result=await req('/admin/api/assistants/'+state.assistantId+'/source-suggestions/'+b.dataset.sourceSuggestionApprove+'/approve',{method:'POST'});toast(en?'Source approved':'منبع تأیید و اضافه شد');await loadAll();const added=state.sources.find(x=>x.source_key===result?.source_key);if(added)window.probeSingleSource?.(added.id)}catch(err){toast(friendlyError(err.message),true)}});
        document.querySelectorAll('[data-source-suggestion-reject]').forEach(b=>b.onclick=async()=>{try{await req('/admin/api/assistants/'+state.assistantId+'/source-suggestions/'+b.dataset.sourceSuggestionReject+'/reject',{method:'POST'});toast(en?'Suggestion rejected':'پیشنهاد رد شد');loadSourceSuggestions()}catch(err){toast(friendlyError(err.message),true)}});
      }catch(err){if($('sourceSuggestionsCard'))$('sourceSuggestionsCard').classList.add('hidden')}
    }
    async function openSourceSuggestionsModal(){
      if(!state.assistantId){toast('ابتدا یک دستیار را انتخاب کنین',true);return}
      const en=state.language==='en';
      modal(en?'Suggest a media source':'پیشنهاد رسانه',`<div class="notice">${en?'Enter a media name. The assistant will prepare an editable draft; only the owner can approve activation.':'نام رسانه را وارد کنین. بات یک پیش‌نویس قابل ویرایش می‌سازد؛ فعال‌سازی فقط با تأیید مالک انجام می‌شود.'}</div><div class="form-grid"><div class="field full"><label>${en?'Media name':'نام رسانه'}</label><input id="suggestSourceName"></div><div class="field full"><label>${en?'Research angle (optional)':'زاویه بررسی (اختیاری)'}</label><textarea id="suggestSourceInstruction"></textarea></div></div>`,async()=>{const name=$('suggestSourceName').value.trim();if(!name){toast(en?'Enter a media name':'نام رسانه را وارد کنین',true);return}try{$('modalSubmit').disabled=true;const r=await req('/admin/api/assistants/'+state.assistantId+'/source-suggestions',{method:'POST',body:JSON.stringify({name,instruction:$('suggestSourceInstruction').value.trim()})});closeModal();toast(en?'Draft source suggestion created':'پیشنهاد پیش‌نویس رسانه ایجاد شد');loadSourceSuggestions()}catch(err){$('modalSubmit').disabled=false;toast(friendlyError(err.message),true)}},en?'Create draft':'ساخت پیش‌نویس');
    }
    function openTemplateBuilder(){
      if(!state.assistantId){toast('ابتدا یک دستیار را انتخاب کنین',true);return}
      req('/admin/api/assistants/'+state.assistantId+'/templates').then(payload=>{
        if(!payload.can_edit){toast(state.language==='en'?'Only the owner can edit templates':'فقط مالک می‌تواند قالب را ویرایش کند',true);return}
      const en=state.language==='en',labels={title:en?'Title':'عنوان',summary:en?'Summary':'خلاصه',business_connection:en?'Business relevance':'ارتباط با بیزینس',opportunity:en?'Opportunity':'فرصت',risk:en?'Risk':'ریسک',source:en?'Source':'منبع',published_at:en?'Published time':'زمان انتشار',source_url:en?'Source link':'لینک منبع',feedback:en?'Feedback buttons':'دکمه‌های بازخورد',footer:en?'Footer':'پاورقی',image:en?'Featured image':'تصویر شاخص'},templates=payload.templates||{};
        let channel='feedback',blocks=JSON.parse(JSON.stringify(templates[channel]?.blocks||[]));
        const sync=()=>{document.querySelectorAll('[data-template-index]').forEach(el=>{const i=Number(el.dataset.templateIndex);const b=blocks[i];if(!b)return;b.label=el.querySelector('[data-template-label]')?.value.trim()||b.label;b.emoji=el.querySelector('[data-template-emoji]')?.value.trim()||'';b.max_chars=Number(el.querySelector('[data-template-max]')?.value||0);b.guidance=el.querySelector('[data-template-guidance]')?.value.trim()||''})};
        const render=()=>{const items=blocks.map((b,i)=>`<div class="channel-card" draggable="true" data-template-index="${i}" data-ui-css="declaration-8"><div class="channel-card-head"><div><b>${esc(labels[b.type]||b.label||b.type)}</b><span class="muted">${esc(b.type)}</span></div><button type="button" class="btn small" data-template-toggle="${i}">${b.visible===false?(en?'Show':'نمایش'):(en?'Hide':'مخفی')}</button></div><div class="form-grid" data-ui-css="declaration-6"><div class="field"><label>${en?'Label':'برچسب'}</label><input data-template-label value="${esc(b.label||'')}"></div><div class="field"><label>${en?'Emoji (optional)':'ایموجی (اختیاری)'}</label><input data-template-emoji value="${esc(b.emoji||'')}" maxlength="16"></div><div class="field"><label>${en?'Maximum characters':'حداکثر کاراکتر'}</label><input data-template-max type="number" min="20" max="1200" value="${esc(b.max_chars||0)}"></div><div class="field full"><label>${en?'Generation guidance':'راهنمای تولید محتوا'}</label><textarea data-template-guidance placeholder="${en?'What should the model consider for this section?':'در تولید این بخش به چه نکاتی توجه شود؟'}">${esc(b.guidance||'')}</textarea></div></div></div>`).join('');$('templateCanvas').innerHTML=items||`<div class="empty">${en?'No blocks':'بلوک خالی است'}</div>`;document.querySelectorAll('[data-template-toggle]').forEach(b=>b.onclick=()=>{sync();const i=Number(b.dataset.templateToggle);blocks[i].visible=blocks[i].visible===false;render()});document.querySelectorAll('[data-template-index]').forEach(el=>{el.ondragstart=e=>e.dataTransfer.setData('text/plain',el.dataset.templateIndex);el.ondragover=e=>e.preventDefault();el.ondrop=e=>{e.preventDefault();sync();const from=Number(e.dataTransfer.getData('text/plain')),to=Number(el.dataset.templateIndex);const moved=blocks.splice(from,1)[0];blocks.splice(to,0,moved);render()}})};
        modal(en?'Content template builder':'سازنده قالب محتوا',`<div class="notice">${en?'Owner-only editor. Drag blocks, set a character limit, emoji and generation guidance, then preview and publish.':'ویرایشگر مخصوص مالک است. بلوک‌ها را جابه‌جا کنید، سقف کاراکتر، ایموجی و راهنمای تولید هر بخش را تعیین کنید، سپس پیش‌نمایش بگیرید و منتشر کنید.'}</div><div class="field"><label>${en?'Destination':'مقصد'}</label><select id="templateChannel"><option value="feedback">${en?'Feedback channel':'کانال فیدبک'}</option><option value="observer">${en?'Observer channel':'کانال مشاهده'}</option></select></div><div id="templateCanvas" data-ui-css="declaration-6"></div><button type="button" class="btn small" id="templatePreviewBtn" data-ui-css="declaration-6">${en?'Preview Telegram message':'پیش‌نمایش پیام تلگرام'}</button><div id="templatePreview" class="article-body hidden" data-ui-css="declaration-6"></div>`,async()=>{try{sync();await req('/admin/api/assistants/'+state.assistantId+'/templates/'+channel,{method:'PUT',body:JSON.stringify({blocks,publish:true})});closeModal();toast(en?'Template published':'قالب منتشر شد')}catch(err){toast(friendlyError(err.message),true)}} ,en?'Publish':'انتشار');
        $('templatePreviewBtn').onclick=async()=>{try{sync();$('templatePreviewBtn').disabled=true;const r=await req('/admin/api/assistants/'+state.assistantId+'/templates/'+channel+'/preview',{method:'POST',body:JSON.stringify({blocks,publish:false})});$('templatePreview').innerHTML=safePreview(r.preview);$('templatePreview').classList.remove('hidden')}catch(err){toast(friendlyError(err.message),true)}finally{$('templatePreviewBtn').disabled=false}};
        $('templateChannel').onchange=()=>{channel=$('templateChannel').value;blocks=JSON.parse(JSON.stringify(templates[channel]?.blocks||[]));$('templatePreview').classList.add('hidden');render()};render();
      }).catch(err=>toast(friendlyError(err.message),true))
    }
