    function localizeCollectionSettings(){const card=$('collectionSettingsCard');if(!card)return;const owner=Boolean(state.currentUser?.is_owner||state.currentUser?.role==='owner');card.classList.toggle('hidden',!owner);if(!owner)return;const c=collectionCopy(),ownerLabels={fa:'فقط مالک',en:'Owner only',tr:'Yalnızca sahip',ar:'للمالك فقط',it:'Solo proprietario',es:'Solo propietario',de:'Nur Eigentümer',fr:'Propriétaire uniquement'},set=(id,value)=>{const node=$(id);if(node)node.textContent=value};set('collectionSettingsTitle',c.title);set('collectionSettingsSubtitle',c.subtitle);set('collectionOwnerBadge',ownerLabels[state.language]||ownerLabels.en);set('collectionSettingsNote',c.note);set('collectionEnabledLabel',c.enabled);set('collectionPerSourceLabel',c.perSource);set('collectionPerSourceHelp',c.perSourceHelp);set('collectionPerRunLabel',c.perRun);set('collectionPerDayLabel',c.perDay);set('collectionPerRunHelp',c.perRunHelp);set('collectionPerDayHelp',c.perDayHelp);set('saveCollectionSettingsBtn',c.save);setCollectionInfoTip('collectionEnabledLabel',c.enabledHelp);setCollectionInfoTip('collectionPerSourceLabel',c.perSourceHelp);setCollectionInfoTip('collectionPerRunLabel',c.perRunHelp);setCollectionInfoTip('collectionPerDayLabel',c.perDayHelp);const defaults={collectionMaxPerSource:50,collectionMaxPerRun:1000,collectionMaxPerDay:1000};Object.entries(defaults).forEach(([id,value])=>{const node=$(id);if(node&&!String(node.value||'').trim())node.value=state.language==='en'?String(value):toFaDigits(value)});if($('collectionEnabled')&&!state.collectionSettings)$('collectionEnabled').checked=true;window.__researchBeeEnhanceInfoTips?.();renderCollectionScheduleGrid()}
    function bindCollectionSave(){const button=$('saveCollectionSettingsBtn');if(!button||button.dataset.bound==='true')return;button.dataset.bound='true';button.onclick=async()=>{const en=state.language==='en',c=collectionCopy();try{if(!state.assistantId)throw Error(en?'Select an assistant first':'ابتدا یک دستیار را انتخاب کنین');const slots=collectCollectionScheduleSlots();if(!slots.length)throw Error(c.select);const parse=(id,min,max)=>{const value=Number(toLatinDigits($(id)?.value||''));if(!Number.isInteger(value)||value<min||value>max)throw Error(en?`${id==='collectionMaxPerSource'?'Per-source':'Collection'} value must be between ${min} and ${max}.`:`مقدار واردشده باید بین ${toFaDigits(min)} و ${toFaDigits(max)} باشد.`);return value};const body={collection_enabled:Boolean($('collectionEnabled')?.checked),collection_schedule_slots:slots,collection_max_items_per_source:parse('collectionMaxPerSource',1,200),collection_max_items_per_run:parse('collectionMaxPerRun',1,1000),collection_max_items_per_day:parse('collectionMaxPerDay',1,1000)};button.disabled=true;const r=await req('/admin/api/assistants/'+state.assistantId+'/runtime-settings',{method:'PUT',body:JSON.stringify(body)});state.runtimeSettings=r;state.collectionScheduleSlots=r.collection_schedule_slots||slots;state.collectionScheduleConfigured=true;state.collectionSettings=r;renderCollectionScheduleGrid();if($('collectionScheduleMsg')){$('collectionScheduleMsg').textContent=c.saved;$('collectionScheduleMsg').className='success'}toast(c.saved)}catch(err){if($('collectionScheduleMsg')){$('collectionScheduleMsg').textContent=friendlyError(err.message);$('collectionScheduleMsg').className='error'}toast(friendlyError(err.message),true)}finally{button.disabled=false}}}
