    async function activateBusiness(id){try{await req('/admin/api/assistants/'+state.assistantId+'/runtime-settings',{method:'PUT',body:JSON.stringify({active_business_id:Number(id)})});toast('بیزینس فعال شد');refreshBusinessUi()}catch(err){toast(friendlyError(err.message),true)}}
