      if(!requested){
        if($('businessGrid'))$('businessGrid').innerHTML=`<div class="empty">${state.language==='en'?'Select an authorized project first.':'ابتدا یک پروژهٔ مجاز را انتخاب کنین.'}</div>`;
        return;
      }
