    function openFeedbackTimeline(actorKey){const actor=(state.feedbackReport?.by_actor||[]).find(x=>String(x.actor_key)===String(actorKey));const timeline=actor?.timeline||[];if(!timeline.length){modal('روند بازخورد کاربر',`<div class="empty">برای این کاربر در بازهٔ ۳۰ روزه بازخوردی ثبت نشده است.</div>`,()=>closeModal(),'بستن');return}const width=680,height=250,pad={l:46,r:18,t:22,b:48},values=timeline.map(x=>Number(x.count||0)),max=Math.max(...values,1),xAt=i=>pad.l+(i*(width-pad.l-pad.r))/Math.max(timeline.length-1,1),yAt=v=>height-pad.b-(v*(height-pad.t-pad.b))/max,points=values.map((v,i)=>`${xAt(i).toFixed(1)},${yAt(v).toFixed(1)}`).join(' '),grid=[0,Math.ceil(max/2),max].filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<line x1="${pad.l}" y1="${yAt(v)}" x2="${width-pad.r}" y2="${yAt(v)}" stroke="#e2e8f0"/><text x="${pad.l-8}" y="${yAt(v)+4}" text-anchor="end" fill="#64748b" font-size="11">${toFaDigits(v)}</text>`).join(''),labels=timeline.map((x,i)=>i===0||i===timeline.length-1||i===Math.floor(timeline.length/2)?`<text x="${xAt(i)}" y="${height-16}" text-anchor="middle" fill="#64748b" font-size="10">${esc(x.date)}</text>`:'').join('');modal('روند ثبت بازخورد: '+esc(actorKey),`<div class="muted" data-ui-css="declaration-10">تعداد بازخورد ثبت‌شده در هر روز (۳۰ روز اخیر)</div><div data-ui-css="declaration-11" dir="ltr"><svg viewBox="0 0 ${width} ${height}" role="img" aria-label="نمودار خطی بازخورد"><g>${grid}</g><polyline points="${points}" fill="none" stroke="#0f766e" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/>${values.map((v,i)=>`<circle cx="${xAt(i)}" cy="${yAt(v)}" r="4" fill="#0f766e"><title>${esc(timeline[i].date)}: ${toFaDigits(v)}</title></circle>`).join('')}${labels}</svg></div><div class="detail-list" data-ui-css="declaration-6"><div class="detail-item"><span>کل</span><b>${toFaDigits(actor.total)}</b></div><div class="detail-item"><span>مرتبط / نامرتبط</span><b>${toFaDigits(actor.up)} / ${toFaDigits(actor.down)}</b></div></div>`,()=>closeModal(),'بستن')}
    function renderQualityReport(report){const r=report||{},actors=Array.isArray(r.by_actor)?r.by_actor:[],en=state.language==='en',num=value=>en?String(Number(value||0)):toFaDigits(Number(value||0)),sum=key=>actors.reduce((total,row)=>total+Number(row?.[key]||0),0),total=Number(r.total_feedback??r.signal_count??r.count??sum('total')),related=Number(r.up??r.related??r.relevant??sum('up')),unrelated=Number(r.down??r.unrelated??r.irrelevant??sum('down')),unique=Number(r.unique_actors??r.uniqueActors??actors.length);state.feedbackReport={...r,total_feedback:total,up:related,down:unrelated,unique_actors:unique};$('qualityTotal').textContent=num(total);$('qualityRelevant').textContent=num(related);$('qualityIrrelevant').textContent=num(unrelated);$('feedbackUniqueActors').textContent=en?`${unique} users`:`${toFaDigits(unique)} کاربر`;$('feedbackReportPeriod').textContent=en?'Last 30 days':'۳۰ روز اخیر';const rows=actors.map(x=>`<tr><td><div class="feedback-user"><span class="feedback-user-mark">@</span><b>${esc(x.actor_key||'—')}</b></div></td><td class="feedback-count">${num(x.total)}</td><td class="feedback-count up">${num(x.up??x.related??x.relevant)}</td><td class="feedback-count down">${num(x.down??x.unrelated??x.irrelevant)}</td><td><button class="btn small feedback-timeline-btn" type="button" data-feedback-actor="${esc(x.actor_key||'')}">${en?'View timeline':'مشاهده روند'}</button></td></tr>`).join('')||`<tr><td colspan="5" class="empty">${en?'No feedback recorded for this project.':'برای این پروژه بازخوردی ثبت نشده است.'}</td></tr>`;$('feedbackActorRows').innerHTML=rows;document.querySelectorAll('.feedback-timeline-btn').forEach(button=>button.onclick=()=>openFeedbackTimeline(button.dataset.feedbackActor));$('qualityReportError').classList.add('hidden');translateStaticCopy()}
    loadQuality=async function(){try{if(!state.assistantId){await loadAll()}if(!state.assistantId){renderQualityReport({});return}const r=await req('/feedback/report?days=30&assistant_id='+encodeURIComponent(state.assistantId));renderQualityReport(r)}catch(err){renderQualityReport({});$('qualityReportError').textContent=friendlyError(err.message);$('qualityReportError').classList.remove('hidden')}};if($('feedbackReportBtn'))$('feedbackReportBtn').onclick=loadQuality;
