    state.sourceSort=state.sourceSort||{key:'name',dir:'asc'};state.topicSort=state.topicSort||{key:'name',dir:'asc'};
    function sortValue(value,key){if(value===null||value===undefined||value==='')return null;if(key==='last_success_at'||key==='created_at'){const time=Date.parse(value);return Number.isNaN(time)?String(value).toLocaleLowerCase('fa'):time}if(['priority','importance','threshold','display_order'].includes(key)){const n=Number(value);return Number.isNaN(n)?null:n}return String(value).toLocaleLowerCase('fa')}
    function compareSort(a,b,key,dir){const av=sortValue(a?.[key],key),bv=sortValue(b?.[key],key);if(av===bv)return 0;if(av===null)return 1;if(bv===null)return -1;const result=typeof av==='number'&&typeof bv==='number'?av-bv:String(av).localeCompare(String(bv),'fa',{numeric:true,sensitivity:'base'});return dir==='desc'?-result:result}
